input.content:
{
  "jiraKey": "SFCC-194",
  "folder": "/Staging/SFCC-194",
  "testCases": [
    {
      "name": "PDP Was/Now Price: displays both original and sale price when a sale price is active",
      "objective": "Proves the PDP renders the original (Was) price alongside the active sale (Now) price when a sale pricebook price applies to the product.",
      "precondition": "A product is assigned an active sale price via a sale pricebook on the ZimmermannAU storefront. The product is in stock and published.",
      "folder": "/Staging/SFCC-194",
      "statusName": "Draft",
      "priorityName": "High",
      "labels": ["SFCC-194", "ai-generated", "needs-review"],
      "linkedIssueKey": "SFCC-194",
      "steps": [
        {
          "description": "Open the PDP for the product that has an active sale price on the ZimmermannAU storefront.",
          "expectedResult": "The page loads and the product's price area is visible without scrolling past the product title."
        },
        {
          "description": "Inspect the price area beneath the product name.",
          "expectedResult": "Two prices are shown: the original list price and the sale price. Both display an AUD amount. Neither price is blank, zero, or shown as a placeholder."
        },
        {
          "description": "Compare the two displayed values against the product's list price and sale price configured in Business Manager.",
          "expectedResult": "The higher value shown matches the configured list price and the lower value shown matches the configured sale price. The sale price is lower than the original price."
        }
      ]
    },
    {
      "name": "PDP Was/Now Price: sale price takes visual prominence over the original price",
      "objective": "Proves the sale price is the visually dominant of the two prices, using the green-on-sale / greyed-out-Was treatment approved by Rebecca.",
      "precondition": "A product with an active sale price on the ZimmermannAU storefront. Designs for SFCC-194 are available to the tester for visual comparison.",
      "folder": "/Staging/SFCC-194",
      "statusName": "Draft",
      "priorityName": "High",
      "labels": ["SFCC-194", "ai-generated", "needs-review"],
      "linkedIssueKey": "SFCC-194",
      "steps": [
        {
          "description": "Open the PDP for the product with an active sale price and look at the price area.",
          "expectedResult": "The sale price renders in green. The original price renders in a muted grey, visibly lower contrast than the sale price."
        },
        {
          "description": "Compare the rendered price area against the approved design.",
          "expectedResult": "The sale price is the more prominent of the two. The original price does not compete with it for attention."
        },
        {
          "description": "Using browser dev tools, check the computed colour of the original (Was) price text against its background.",
          "expectedResult": "The contrast ratio meets WCAG 2.2 AA for the text size in use (4.5:1 for normal text, 3:1 for large text). Record the measured ratio in the execution notes."
        }
      ]
    },
    {
      "name": "PDP Was/Now Price: displays only the standard price when no sale price is active",
      "objective": "Proves that a product without an active sale price shows a single price, with no empty Was slot or placeholder.",
      "precondition": "A product with no active sale pricebook price on the ZimmermannAU storefront. The product is in stock and published.",
      "folder": "/Staging/SFCC-194",
      "statusName": "Draft",
      "priorityName": "High",
      "labels": ["SFCC-194", "ai-generated", "needs-review"],
      "linkedIssueKey": "SFCC-194",
      "steps": [
        {
          "description": "Open the PDP for the product that has no active sale price.",
          "expectedResult": "Exactly one price is displayed in the price area."
        },
        {
          "description": "Inspect the price area for any residual Was/Now markup.",
          "expectedResult": "No second price, no struck-through or greyed value, no empty element, and no placeholder text such as a dash or 'Was —' is rendered. The single price is shown in the standard (non-sale) treatment, not in the green sale treatment."
        }
      ]
    },
    {
      "name": "PDP Was/Now Price: renders correct currency on each domestic storefront",
      "objective": "Proves Was/Now prices display in the storefront's configured currency across the four domestic storefronts.",
      "precondition": "The same product carries an active sale price on ZimmermannAU, ZimmermannUS, ZimmermannUK, and ZimmermannEU.",
      "folder": "/Staging/SFCC-194",
      "statusName": "Draft",
      "priorityName": "High",
      "labels": ["SFCC-194", "ai-generated", "needs-review"],
      "linkedIssueKey": "SFCC-194",
      "steps": [
        {
          "description": "Open the product PDP on ZimmermannAU (locale 'en').",
          "expectedResult": "Both Was and Now prices display in AUD."
        },
        {
          "description": "Open the same product PDP on ZimmermannUS (locale 'en-US').",
          "expectedResult": "Both Was and Now prices display in USD. Prices are shown exclusive of tax, per the US storefront tax-display rule."
        },
        {
          "description": "Open the same product PDP on ZimmermannUK (locale 'en-GB').",
          "expectedResult": "Both Was and Now prices display in GBP, inclusive of VAT."
        },
        {
          "description": "Open the same product PDP on ZimmermannEU (locale 'en-GB').",
          "expectedResult": "Both Was and Now prices display in EUR, inclusive of VAT."
        },
        {
          "description": "Across all four storefronts, confirm both prices use the same currency as each other.",
          "expectedResult": "On every storefront the Was and Now prices are in the same currency. No storefront shows a mixed-currency pair."
        }
      ]
    },
    {
      "name": "PDP Was/Now Price: renders correct currency on each international storefront",
      "objective": "Proves Was/Now prices display in the storefront's configured currency across the four Global-e international storefronts, including the non-obvious HK and ME currency mappings.",
      "precondition": "The same product carries an active sale price on ZimmermannUSIntl, ZimmermannEUIntl, ZimmermannHK, and ZimmermannME. NOTE: international pricing display depends on the Global-e pricing mechanism (PRC-34..PRC-43), which is not signed off at time of writing — this case may not be executable until that lands.",
      "folder": "/Staging/SFCC-194",
      "statusName": "Draft",
      "priorityName": "High",
      "labels": ["SFCC-194", "ai-generated", "needs-review"],
      "linkedIssueKey": "SFCC-194",
      "steps": [
        {
          "description": "Open the product PDP on ZimmermannUSIntl (locale 'en-CA', path /en-ca/).",
          "expectedResult": "Both Was and Now prices display in USD — not CAD, despite the en-CA locale."
        },
        {
          "description": "Open the same product PDP on ZimmermannEUIntl (locale 'en-CH').",
          "expectedResult": "Both Was and Now prices display in EUR — not CHF, despite the en-CH locale."
        },
        {
          "description": "Open the same product PDP on ZimmermannHK (locale 'en-HK').",
          "expectedResult": "Both Was and Now prices display in USD — not HKD."
        },
        {
          "description": "Open the same product PDP on ZimmermannME (locale 'en-AE').",
          "expectedResult": "Both Was and Now prices display in EUR — not AED."
        }
      ]
    },
    {
      "name": "PDP Was/Now Price: applies locale-correct EUR formatting across EU locales",
      "objective": "Proves that the shared EUR price renders with the decimal separator, thousand separator, and symbol position appropriate to each EU locale rather than a single hardcoded format.",
      "precondition": "A product with an active sale price on ZimmermannEU, priced above 1,000 EUR so thousand separators are exercised.",
      "folder": "/Staging/SFCC-194",
      "statusName": "Draft",
      "priorityName": "High",
      "labels": ["SFCC-194", "ai-generated", "needs-review"],
      "linkedIssueKey": "SFCC-194",
      "steps": [
        {
          "description": "Open the product PDP on ZimmermannEU with locale 'en-GB' and record the exact rendered Was and Now strings.",
          "expectedResult": "Both prices render in EUR using the formatting configured for that locale. Record the exact strings, including symbol position and separators."
        },
        {
          "description": "Repeat on locale 'fr' and record the exact rendered strings.",
          "expectedResult": "Both prices render in EUR using French formatting conventions. The format differs from 'en-GB' where the locale conventions differ."
        },
        {
          "description": "Repeat on locale 'it' and record the exact rendered strings.",
          "expectedResult": "Both prices render in EUR using Italian formatting conventions."
        },
        {
          "description": "Repeat on locale 'es' and record the exact rendered strings.",
          "expectedResult": "Both prices render in EUR using Spanish formatting conventions."
        },
        {
          "description": "Compare the four recorded formats.",
          "expectedResult": "Formatting follows each locale's own convention. The same raw amount is never rendered with an incorrect separator for that locale (for example, a decimal comma shown where the locale expects a decimal point)."
        }
      ]
    },
    {
      "name": "PDP Was/Now Price: retains the original Was price after a second price change",
      "objective": "Proves that when an already-discounted product is discounted again, only the Now price updates and the Was price continues to show the original list price (REG-042).",
      "precondition": "A product with an active sale price on the ZimmermannAU storefront. The tester has Business Manager access to change the sale price and re-index.",
      "folder": "/Staging/SFCC-194",
      "statusName": "Draft",
      "priorityName": "High",
      "labels": ["SFCC-194", "ai-generated", "needs-review"],
      "linkedIssueKey": "SFCC-194",
      "steps": [
        {
          "description": "Open the product PDP and record both the Was value and the Now value.",
          "expectedResult": "Both prices are displayed. Record the two values."
        },
        {
          "description": "In Business Manager, reduce the product's sale price to a lower value than currently set. Allow pricing to propagate and re-index.",
          "expectedResult": "The new sale price is saved and active in Business Manager."
        },
        {
          "description": "Reload the product PDP and compare both displayed values against those recorded in step 1.",
          "expectedResult": "The Now price has changed to the newly configured lower sale price. The Was price is unchanged and still shows the original list price recorded in step 1 — it has NOT been reset to the previous sale price."
        }
      ]
    }
  ]
}

