input.new_string:
          "description": "Reload the product PDP and compare both displayed values against those recorded in step 1.",
          "expectedResult": "The Now price has changed to the newly configured lower sale price. The Was price is unchanged and still shows the original list price recorded in step 1 — it has NOT been reset to the previous sale price."
        }
      ]
    },
    {
      "name": "PDP Was/Now Price: reverts to standard price display when the sale price is removed",
      "objective": "Proves that removing an active sale price in Business Manager clears the Was/Now treatment on the PDP, leaving only the standard price.",
      "precondition": "A product with an active sale price on the ZimmermannAU storefront. The tester has Business Manager access to remove the sale price and re-index.",
      "folder": "/Staging/SFCC-194",
      "statusName": "Draft",
      "priorityName": "High",
      "labels": ["SFCC-194", "ai-generated", "needs-review"],
      "linkedIssueKey": "SFCC-194",
      "steps": [
        {
          "description": "Open the product PDP and confirm the starting state, recording both displayed values.",
          "expectedResult": "Both a Was and a Now price are displayed, with the sale price in the green treatment. Record the original list price value."
        },
        {
          "description": "In Business Manager, remove the product's sale price from the sale pricebook. Allow pricing to propagate and re-index.",
          "expectedResult": "The product no longer has an active sale price in Business Manager."
        },
        {
          "description": "Reload the product PDP and inspect the price area.",
          "expectedResult": "Exactly one price is displayed, matching the original list price recorded in step 1. The green sale treatment is gone, no greyed Was price remains, and no empty element or placeholder is left behind."
        }
      ]
    },
    {
      "name": "PDP Was/Now Price: reverts to standard price display when the sale price expires",
      "objective": "Proves that a sale price lapsing at its scheduled end time clears the Was/Now treatment on the next render, without requiring a manual change.",
      "precondition": "A product on the ZimmermannAU storefront with a sale price scheduled to expire at a known date and time in the near future. The tester has Business Manager access to set the schedule.",
      "folder": "/Staging/SFCC-194",
      "statusName": "Draft",
      "priorityName": "High",
      "labels": ["SFCC-194", "ai-generated", "needs-review"],
      "linkedIssueKey": "SFCC-194",
      "steps": [
        {
          "description": "Before the scheduled expiry time, open the product PDP and record both displayed values and the expiry time.",
          "expectedResult": "Both a Was and a Now price are displayed. Record the original list price and the configured expiry timestamp."
        },
        {
          "description": "Wait until after the scheduled expiry time has passed, then reload the product PDP.",
          "expectedResult": "Exactly one price is displayed, matching the original list price recorded in step 1. No Was/Now treatment remains."
        },
        {
          "description": "Confirm no manual Business Manager action was needed to produce the change.",
          "expectedResult": "The reversion happened purely from the schedule lapsing. The tester made no edit to the product or pricebook between step 1 and step 2."
        }
      ]
    }
  ]
}

